    FOREIGN KEY (order_id, parent_line_id) REFERENCES rental_order_lines (order_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE CASCADE,
    FOREIGN KEY (class_id) REFERENCES rental_classes (id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE RESTRICT,
    FOREIGN KEY (rate_card_id) REFERENCES rental_rate_cards (id) ON DELETE RESTRICT,
    FOREIGN KEY (stock_movement_id) REFERENCES stock_movements (id) ON DELETE RESTRICT
) STRICT;
