    SELECT id, created_at, updated_at, created_by, updated_by, version, asset_id, order_id, line_no, kind, class_id, product_id, fee_id, parent_line_id, location_id, description, qty_micros, start_at, end_at, actual_out_at, actual_in_at, rate_card_id, price_snapshot, unit_price_minor, amount_minor, discount_minor, discount_bp, taxable, tax_profile_id, tax_snapshot, tax_minor, price_overridden_by, override_reason, status, invoiced_through, stock_issued_at, stock_movement_id, assign_unit_later, kit_id, kit_component_id, kit_instance_id FROM rental_order_lines;
