-- rebuild rental_contracts
CREATE TABLE rental_contracts__v2_new (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    number TEXT NOT NULL,
    order_id TEXT NOT NULL CHECK (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*'),
    customer_party_id TEXT CHECK (customer_party_id IS NULL OR (length(customer_party_id) = 36 AND customer_party_id NOT GLOB '*[^0-9a-f-]*')),
    kind TEXT NOT NULL CHECK ((length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*') AND (kind IN ('long_term', 'rent_to_own'))),
    term TEXT NOT NULL CHECK ((length(term) BETWEEN 1 AND 63 AND term GLOB '[a-z]*' AND term NOT GLOB '*[^a-z0-9_]*') AND (term IN ('open_ended', 'fixed'))),
    status TEXT NOT NULL CHECK ((length(status) BETWEEN 1 AND 63 AND status GLOB '[a-z]*' AND status NOT GLOB '*[^a-z0-9_]*') AND (status IN ('draft', 'active', 'notice_given', 'ended', 'bought_out', 'terminated'))),
    start_at INTEGER NOT NULL,
    end_at INTEGER,
    min_term_months INTEGER NOT NULL DEFAULT 0,
    notice_days INTEGER NOT NULL DEFAULT 30,
    notice_given_at INTEGER,
    ends_by_notice_at INTEGER,
    billing_timing TEXT NOT NULL CHECK ((length(billing_timing) BETWEEN 1 AND 63 AND billing_timing GLOB '[a-z]*' AND billing_timing NOT GLOB '*[^a-z0-9_]*') AND (billing_timing IN ('advance', 'arrears'))),
    proration TEXT NOT NULL CHECK ((length(proration) BETWEEN 1 AND 63 AND proration GLOB '[a-z]*' AND proration NOT GLOB '*[^a-z0-9_]*') AND (proration IN ('daily', 'none'))),
    monthly_rate_minor INTEGER NOT NULL,
    currency TEXT NOT NULL CHECK (length(currency) = 3 AND currency NOT GLOB '*[^A-Z]*'),
    tax_profile_id TEXT CHECK (tax_profile_id IS NULL OR (length(tax_profile_id) = 36 AND tax_profile_id NOT GLOB '*[^0-9a-f-]*')),
    escalation_at INTEGER,
    escalation_bp INTEGER NOT NULL DEFAULT 0,
    escalation_every_months INTEGER,
    early_termination_fee_minor INTEGER NOT NULL DEFAULT 0,
    early_termination_remaining_bp INTEGER NOT NULL DEFAULT 0,
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    purchase_price_minor INTEGER,
    equity_bp INTEGER NOT NULL DEFAULT 0,
    buyout_floor_minor INTEGER NOT NULL DEFAULT 0,
    equity_adjustment_minor INTEGER NOT NULL DEFAULT 0,
    bought_out_at INTEGER,
    buyout_invoice_id TEXT CHECK (buyout_invoice_id IS NULL OR (length(buyout_invoice_id) = 36 AND buyout_invoice_id NOT GLOB '*[^0-9a-f-]*')),
    terminated_at INTEGER,
    termination_reason TEXT,
    notes TEXT,
    PRIMARY KEY (id),
    CHECK (end_at IS NULL OR start_at < end_at),
    CHECK (term <> 'fixed' OR end_at IS NOT NULL),
    CHECK (kind <> 'rent_to_own' OR (asset_id IS NOT NULL AND purchase_price_minor IS NOT NULL)),
    CHECK (escalation_bp >= 0 AND equity_bp BETWEEN 0 AND 10000 AND early_termination_remaining_bp BETWEEN 0 AND 10000),
    FOREIGN KEY (order_id) REFERENCES rental_orders (id) ON DELETE RESTRICT,
    FOREIGN KEY (customer_party_id) REFERENCES parties (id) ON DELETE RESTRICT,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (buyout_invoice_id) REFERENCES invoices (id) ON DELETE RESTRICT
) STRICT;
INSERT INTO rental_contracts__v2_new (id, created_at, updated_at, created_by, updated_by, version, number, order_id, customer_party_id, kind, term, status, start_at, end_at, min_term_months, notice_days, notice_given_at, ends_by_notice_at, billing_timing, proration, monthly_rate_minor, currency, tax_profile_id, escalation_at, escalation_bp, escalation_every_months, early_termination_fee_minor, early_termination_remaining_bp, asset_id, purchase_price_minor, equity_bp, buyout_floor_minor, equity_adjustment_minor, bought_out_at, buyout_invoice_id, terminated_at, termination_reason, notes)
    SELECT id, created_at, updated_at, created_by, updated_by, version, number, order_id, customer_party_id, kind, term, status, start_at, end_at, min_term_months, notice_days, notice_given_at, ends_by_notice_at, billing_timing, proration, monthly_rate_minor, currency, tax_profile_id, escalation_at, escalation_bp, escalation_every_months, early_termination_fee_minor, early_termination_remaining_bp, asset_id, purchase_price_minor, equity_bp, buyout_floor_minor, equity_adjustment_minor, bought_out_at, buyout_invoice_id, terminated_at, termination_reason, notes FROM rental_contracts;
DROP TABLE rental_contracts;
ALTER TABLE rental_contracts__v2_new RENAME TO rental_contracts;

-- rebuild invoice_lines
CREATE TABLE invoice_lines__v2_new (
    id TEXT NOT NULL CHECK (length(id) = 36 AND id NOT GLOB '*[^0-9a-f-]*'),
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    created_by TEXT CHECK (created_by IS NULL OR (length(created_by) = 36 AND created_by NOT GLOB '*[^0-9a-f-]*')),
    updated_by TEXT CHECK (updated_by IS NULL OR (length(updated_by) = 36 AND updated_by NOT GLOB '*[^0-9a-f-]*')),
    version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
    invoice_id TEXT NOT NULL CHECK (length(invoice_id) = 36 AND invoice_id NOT GLOB '*[^0-9a-f-]*'),
    line_no INTEGER NOT NULL CHECK (line_no >= 1),
    kind TEXT NOT NULL DEFAULT 'item' CHECK (length(kind) BETWEEN 1 AND 63 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_]*'),
    description TEXT NOT NULL,
    order_id TEXT CHECK (order_id IS NULL OR (length(order_id) = 36 AND order_id NOT GLOB '*[^0-9a-f-]*')),
    order_line_id TEXT CHECK (order_line_id IS NULL OR (length(order_line_id) = 36 AND order_line_id NOT GLOB '*[^0-9a-f-]*')),
    asset_id TEXT CHECK (asset_id IS NULL OR (length(asset_id) = 36 AND asset_id NOT GLOB '*[^0-9a-f-]*')),
    product_id TEXT CHECK (product_id IS NULL OR (length(product_id) = 36 AND product_id NOT GLOB '*[^0-9a-f-]*')),
    qty_micros INTEGER NOT NULL,
    unit TEXT CHECK (unit IS NULL OR (length(unit) BETWEEN 1 AND 63 AND unit GLOB '[a-z]*' AND unit NOT GLOB '*[^a-z0-9_]*')),
    unit_price TEXT NOT NULL CHECK (unit_price NOT GLOB '*[^0-9.-]*' AND length(unit_price) BETWEEN 1 AND 40),
    discount_minor INTEGER NOT NULL DEFAULT 0,
    amount_minor INTEGER NOT NULL,
    tax_minor INTEGER NOT NULL DEFAULT 0,
    tax_profile_id TEXT CHECK (tax_profile_id IS NULL OR (length(tax_profile_id) = 36 AND tax_profile_id NOT GLOB '*[^0-9a-f-]*')),
    tax_snapshot TEXT NOT NULL CHECK (json_valid(tax_snapshot)),
    service_period_start INTEGER,
    service_period_end INTEGER,
    PRIMARY KEY (id),
    CHECK (order_line_id IS NULL OR order_id IS NOT NULL),
    FOREIGN KEY (order_id, order_line_id) REFERENCES rental_order_lines (order_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (invoice_id) REFERENCES invoices (id) ON DELETE CASCADE,
    FOREIGN KEY (asset_id) REFERENCES assets (id) ON DELETE RESTRICT,
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT
) STRICT;
INSERT INTO invoice_lines__v2_new (id, created_at, updated_at, created_by, updated_by, version, invoice_id, line_no, kind, description, order_id, order_line_id, asset_id, product_id, qty_micros, unit, unit_price, discount_minor, amount_minor, tax_minor, tax_profile_id, tax_snapshot, service_period_start, service_period_end)
    SELECT id, created_at, updated_at, created_by, updated_by, version, invoice_id, line_no, kind, description, order_id, order_line_id, asset_id, product_id, qty_micros, unit, unit_price, discount_minor, amount_minor, tax_minor, tax_profile_id, tax_snapshot, service_period_start, service_period_end FROM invoice_lines;
DROP TABLE invoice_lines;
ALTER TABLE invoice_lines__v2_new RENAME TO invoice_lines;

